#!/usr/bin/env python
"""Retired preprocessor; JoSIM owns thermal noise through native controls."""
import sys


def main():
    print("noise_insert.py is retired. Use native .TEMP (kelvin) and .NEB (Hz) "
          "controls, or TEMP=/NEB= on individual resistors and junctions. "
          "These controls evaluate engineering suffixes, parameters and active "
          "junction conductance within JoSIM. Do not combine native thermal "
          "noise with currents generated by the old script. No files were changed.",
          file=sys.stderr)
    return 2


if __name__ == "__main__":
    raise SystemExit(main())
